import html.parser
class Validator(html.parser.HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.errors = []
    def handle_starttag(self, tag, attrs):
        if tag not in ['br','hr','img','input','meta','link','area','base','col','embed','param','source','track','wbr']:
            self.stack.append(tag)
    def handle_endtag(self, tag):
        if tag not in ['br','hr','img','input','meta','link','area','base','col','embed','param','source','track','wbr']:
            if self.stack and self.stack[-1] == tag:
                self.stack.pop()
            else:
                self.errors.append(f'Unexpected </{tag}>')
v = Validator()
with open('index.html') as f:
    v.feed(f.read())
if v.stack:
    print('Unclosed tags:', v.stack)
if v.errors:
    print('Errors:', v.errors)
if not v.stack and not v.errors:
    print('HTML structure valid')
